// Talent V2 extends the current in-memory prototype. TODO: persist these fields through the future talent data model.
const talentV2={status:'Open to Opportunities',confirmedAt:null,profileUpdatedAt:null,salaryConfirmedAt:null,headline:'',summary:'',roles:[],industries:[],preferredLocation:'',arrangement:'No Preference',employmentType:'Full-time',minimumSalary:'',preferredSalary:'',notice:'',skills:[],achievements:[],experienceExtras:[{},{},{}],priorities:{},visibility:'Hidden',blockedEmployer:'',jobStage:'Recommended',exampleStage:'Recommended',declineReason:''};
const legacyBody=body,legacyProfilePage=profilePage,legacyCaptureProfile=captureProfile,legacyCompleteProfile=completeProfile,legacyWithdrawDiscovery=withdrawDiscovery;
const nowDate=()=>new Date().toISOString();
const when=iso=>iso?new Date(iso).toLocaleDateString('en-SG',{day:'numeric',month:'short',year:'numeric'}):'Not confirmed';
const workFields=['job','salary','qualification','language','start','living','location'];
function strength(){const items=[['Add a professional headline',!!talentV2.headline,'profile'],['Write a professional summary',talentV2.summary.length>=80,'profile'],['Choose preferred roles',talentV2.roles.length>0,'preferences'],['Add a skill',talentV2.skills.some(x=>x.name),'profile'],['Add two achievements',talentV2.achievements.filter(Boolean).length>=2,'profile'],['Confirm availability',!!talentV2.confirmedAt,'overview'],['Add an expected salary',!!talentDraft.salary,'profile'],['Complete career basics',workFields.every(k=>!!talentDraft[k]),'profile']];return {percent:Math.round(items.filter(x=>x[1]).length/items.length*100),missing:items.filter(x=>!x[1])}}
function talentBody(){if(state.mode!=='talent')return legacyBody();switch(state.view){case 'overview':return overviewPage();case 'profile':return profilePage();case 'preferences':return preferencesPage();case 'opportunities':return starsPage();case 'interest':return interestPage();case 'privacy':return privacyPage();default:return legacyBody()}}
body=talentBody;
function overviewPage(){const score=strength(),first=talentDraft.name||state.profile.name||'there',greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening',pending=state.requests.filter(r=>r.status==='Awaiting response').length;return `<div class="heading"><div><div class="eyebrow">CAREER COMMAND CENTRE</div><h1>${greeting}, ${esc(first.split(' ')[0])}.</h1><p class="sub">${talentDraft.discovery&&talentV2.visibility!=='Hidden'?'Employer visibility selected in this demo.':'Your profile is private in this demo.'}</p></div><button class="btn" onclick="navigate('profile')">Edit profile</button></div><div class="v2-summary"><div><span>Profile strength</span><strong>${score.percent}%</strong><progress max="100" value="${score.percent}" aria-label="Profile strength ${score.percent} percent"></progress></div><div><span>Opportunity status</span><strong>${esc(talentV2.status)}</strong><small>Confirmed ${when(talentV2.confirmedAt)}</small></div><div><span>Stars matches</span><strong>—</strong><small>No live matching feed yet</small></div><div><span>Employer interest</span><strong>${pending}</strong><small>Pending demo introduction${pending===1?'':'s'}</small></div></div><div class="v2-columns"><section class="panel"><div class="section-head"><h2>Opportunity status</h2><span>Last confirmed ${when(talentV2.confirmedAt)}</span></div><p class="sub">Tell Stars whether relevant employers should approach you.</p><div class="status-options">${[['Actively Looking','I am actively searching.'],['Open to Opportunities','I am open to highly relevant roles.'],['Not Looking','Do not recommend me for roles.']].map(([v,d])=>`<label class="status-choice"><input type="radio" name="opportunity-status" value="${v}" ${talentV2.status===v?'checked':''} onchange="setOpportunityStatus(this.value)"><span><strong>${v}</strong><small>${d}</small></span></label>`).join('')}</div><button class="btn primary" onclick="confirmOpportunityStatus()">Confirm status</button><p class="field-note">Status changes are a session-only preview; live matching is not connected.</p></section><section class="panel"><div class="section-head"><h2>Strengthen your profile</h2><span>${score.percent}% complete</span></div><p class="sub">Career information only; optional personal details do not affect this score.</p><ul class="v2-suggestions">${score.missing.slice(0,3).map(([label,,view])=>`<li><button onclick="navigate('${view}')">${esc(label)} ↗</button></li>`).join('')||'<li>Your key career information is covered.</li>'}</ul><div class="v2-divider"></div><h2>Profile activity</h2><dl class="activity-list"><dt>Profile updated</dt><dd>${when(talentV2.profileUpdatedAt)}</dd><dt>Availability confirmed</dt><dd>${when(talentV2.confirmedAt)}</dd><dt>Salary confirmed</dt><dd>${when(talentV2.salaryConfirmedAt)}</dd><dt>Resume updated</dt><dd>No résumé uploaded</dd></dl></section></div><section class="panel v2-wide"><div class="section-head"><h2>What needs your attention</h2><span>${pending} pending</span></div>${pending?`<p>${pending} company introduction${pending===1?'':'s'} awaiting your response.</p><button class="btn primary" onclick="navigate('interest')">Review interest</button>`:'<p>No employer introductions yet. You can review your profile and preferences while we prepare live matching.</p>'}</section>`}
function setOpportunityStatus(value){talentV2.status=value;talentV2.confirmedAt=null;render()}
function confirmOpportunityStatus(){talentV2.confirmedAt=nowDate();render();toast('Opportunity status confirmed for this demo session.')}
const industries=['Technology','AI','SaaS','FMCG','Retail','Finance','Healthcare','Hospitality','Logistics','Marketing','Other'];
const importance=['Not important','Somewhat important','Very important'];
function preferencesPage(){return heading('YOUR NEXT ROLE','What are you looking for?','These choices help shape future recommendations. They stay in this demo session.')+`<form class="panel v2-form" onsubmit="savePreferences(event)" oninput="capturePreferences(this)" onchange="capturePreferences(this)"><div class="section-head"><h2>Roles and industries</h2><span>Up to 5 roles</span></div><label>Preferred roles <span class="field-note">Enter one role per line</span><textarea name="roles" maxlength="300" placeholder="Business Development Executive&#10;Account Manager">${esc(talentV2.roles.join('\n'))}</textarea></label><fieldset class="v2-fieldset"><legend>Preferred industries</legend><div class="choice-grid">${industries.map(x=>`<label><input type="checkbox" name="industries" value="${x}" ${talentV2.industries.includes(x)?'checked':''}>${x}</label>`).join('')}</div></fieldset><div class="form-grid"><label>Preferred location<select name="preferredLocation">${['','Singapore','Malaysia','Remote','Other'].map(x=>`<option value="${x}" ${talentV2.preferredLocation===x?'selected':''}>${x||'Select location'}</option>`).join('')}</select></label><label>Work arrangement<select name="arrangement">${['Office','Hybrid','Remote','No Preference'].map(x=>`<option ${talentV2.arrangement===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Employment type<select name="employmentType">${['Full-time','Part-time','Contract','Freelance','Internship'].map(x=>`<option ${talentV2.employmentType===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Notice period<select name="notice">${['','Immediately','1 Week','2 Weeks','1 Month','2 Months','3 Months+','Custom'].map(x=>`<option ${talentV2.notice===x?'selected':''}>${x||'Select notice period'}</option>`).join('')}</select></label><label>Minimum expected salary<input type="number" min="0" name="minimumSalary" value="${esc(talentV2.minimumSalary)}" placeholder="e.g. 4500"></label><label>Preferred salary<input type="number" min="0" name="preferredSalary" value="${esc(talentV2.preferredSalary)}" placeholder="e.g. 5000"></label></div><p class="field-note">Currency: ${esc(talentDraft.currency||'SGD')}. Your existing expected salary remains in My Profile. Salary preferences are private in this demo.</p><div class="v2-divider"></div><h2>What matters to you?</h2><p class="sub">Choose how strongly each factor affects an opportunity.</p><div class="priority-list">${['Salary','Career Progression','Industry','Work Flexibility','Company Size','Role Seniority'].map(x=>`<label>${x}<select name="priority_${x.replaceAll(' ','_')}">${importance.map(v=>`<option ${talentV2.priorities[x]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><div class="actions"><button type="submit" class="btn primary">Save preferences</button></div></form>`}
function capturePreferences(form){const f=new FormData(form);const roles=String(f.get('roles')||'').split(/[\n,]/).map(x=>x.trim()).filter(Boolean);if(roles.length>5){form.querySelector('[name=roles]').setCustomValidity('Choose up to five preferred roles.');return}form.querySelector('[name=roles]').setCustomValidity('');talentV2.roles=roles;talentV2.industries=f.getAll('industries');for(const key of ['preferredLocation','arrangement','employmentType','notice','minimumSalary','preferredSalary'])talentV2[key]=String(f.get(key)||'');for(const name of ['Salary','Career Progression','Industry','Work Flexibility','Company Size','Role Seniority'])talentV2.priorities[name]=String(f.get('priority_'+name.replaceAll(' ','_'))||'Not important')}
function savePreferences(e){e.preventDefault();capturePreferences(e.target);if(talentV2.preferredSalary&&talentV2.minimumSalary&&Number(talentV2.preferredSalary)<Number(talentV2.minimumSalary)){toast('Preferred salary must be at least the minimum.');return}talentV2.profileUpdatedAt=nowDate();render();toast('Preferences saved for this demo session.')}
const exampleJob={id:'sample-1',title:'Business Development Executive',company:'Example Technology',salary:'SGD 4,500–5,500',location:'Singapore',arrangement:'Hybrid',reason:['B2B experience','Salary and location may align','Partnerships background relevant']};
function starsPage(){const tabs=['Recommended','Interested','Interviewing','Offers','Archived'],stage=talentV2.jobStage;return heading('CURATED FOR YOU','My Stars','A focused view of opportunities and your progress.')+`<div class="prototype-note">Example opportunity only. No live jobs or match calculation are connected.</div><div class="v2-tabs" role="tablist" aria-label="Opportunity stages">${tabs.map(x=>`<button role="tab" aria-selected="${stage===x}" class="${stage===x?'active':''}" onclick="talentV2.jobStage='${x}';render()">${x}</button>`).join('')}</div>${stage===talentV2.exampleStage&&['Recommended','Interested','Archived'].includes(stage)?`<article class="panel job-card"><div class="section-head"><span class="badge">Sample opportunity · Match score unavailable</span><span>Example only</span></div><h2>${exampleJob.title}</h2><p class="sub">${exampleJob.company} · ${exampleJob.location} · ${exampleJob.arrangement} · ${exampleJob.salary}</p><div class="fit"><strong>Why this could fit</strong>${exampleJob.reason.map(x=>`<div>✓ ${x}</div>`).join('')}<div>△ Needs verification against your actual preferences</div></div><div class="actions"><button class="btn primary" onclick="setExampleStage('Interested')">I'm interested</button><button class="btn" onclick="declineExample()">Not for me</button><button class="btn" onclick="viewExample()">View opportunity</button></div></article>`:`<section class="panel empty"><h2>No ${stage.toLowerCase()} opportunities in this demo</h2><p>Live recommendations and application tracking need a job source and matching service.</p></section>`}`}
function setExampleStage(stage){talentV2.exampleStage=stage;talentV2.jobStage=stage;render();toast(`Sample opportunity moved to ${stage}.`)}
function viewExample(){modal(`<div class="eyebrow">SAMPLE OPPORTUNITY</div><h2>${exampleJob.title}</h2><p class="sub">${exampleJob.company} · ${exampleJob.location} · ${exampleJob.arrangement}</p><p class="sub">${exampleJob.salary}</p><div class="callout">Illustrative listing only. There is no employer posting or application behind this card.</div><button class="btn" onclick="document.querySelector('#modal').close()">Close</button>`)}
function declineExample(){modal(`<h2>Why isn't this suitable?</h2><p class="sub">Your feedback stays in this demo session.</p><form onsubmit="submitDecline(event)"><label>Reason (optional)<select name="reason"><option value="">Skip feedback</option>${['Salary Too Low','Wrong Industry','Wrong Location','Wrong Role','Too Senior','Too Junior','Not Interested in Company','Working Arrangement','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><div class="actions"><button class="btn primary" type="submit">Archive opportunity</button></div></form>`)}
function submitDecline(e){e.preventDefault();talentV2.declineReason=String(new FormData(e.target).get('reason')||'');document.querySelector('#modal').close();setExampleStage('Archived')}
function interestPage(){return heading('EMPLOYER INTEREST','Companies interested in you','Decide whether to start each conversation.')+`<div class="prototype-note">Introductions here are simulated from the Employer view. No real messages are sent.</div>${state.requests.length?state.requests.map(r=>requestCard(r,true)).join(''):`<section class="panel empty"><h2>No company introductions yet</h2><p>When a company requests a conversation, you can accept or decline here.</p></section>`}`}
function privacyPage(){return heading('CONTROL YOUR EXPOSURE','Privacy & visibility','Choose how employers may discover you when live access controls are implemented.')+`<div class="prototype-note">Preview settings only. This static prototype has no employer authentication, visibility enforcement, or exclusion list. Do not enter real personal or employer information.</div><div class="v2-columns"><section class="panel"><h2>Profile visibility</h2><p class="sub">Employer discovery still requires your separate consent in My Profile.</p><div class="status-options">${[['Public','Verified employers may discover your professional profile.'],['Matched Employers Only','Only employers with a relevant opportunity should discover you.'],['Anonymous','Hide your name and identifying details in the initial preview.'],['Hidden','Do not show your profile to employers.']].map(([v,d])=>`<label class="status-choice"><input type="radio" name="visibility-v2" value="${v}" ${talentV2.visibility===v?'checked':''} onchange="setVisibility(this.value)"><span><strong>${v}</strong><small>${d}</small></span></label>`).join('')}</div><button class="btn" onclick="previewEmployer()">Preview employer view</button></section><section class="panel"><h2>Hide my profile from</h2><p class="sub">This setting needs company identity checks before it can protect you in production.</p><label>Current employer / company name<input maxlength="120" value="${esc(talentV2.blockedEmployer)}" oninput="talentV2.blockedEmployer=this.value" placeholder="Company name for demo only"></label><p class="field-note">TODO: Persist company exclusions and enforce them at search, matching and introduction access.</p><div class="v2-divider"></div><h2>Consent</h2><p class="sub">Employer discovery consent: <strong>${talentDraft.discovery?'selected':'off'}</strong></p><div class="actions"><button class="btn" onclick="navigate('profile')">Review consent terms</button><button class="text-btn" onclick="withdrawDiscovery()">Withdraw discovery consent</button></div></section></div>`}
function setVisibility(value){talentV2.visibility=value;if(value==='Hidden'&&talentDraft.discovery)legacyWithdrawDiscovery();else {render();toast(value==='Hidden'?'Profile set to hidden in this demo.':'Visibility preview updated. Employer discovery also requires consent.')}}
const profileV1=profilePage;
const jobFieldsV1=jobFields;
jobFields=function(i){const h=talentV2.experienceExtras[i]||{};const entry=jobFieldsV1(i).replace('</fieldset>',`<div class="v2-divider"></div><p class="field-note">Optional context / 可选工作详情</p><div class="form-grid"><label>Employment type<select name="v2_history_${i}_type">${['','Full-time','Part-time','Contract','Freelance','Internship'].map(v=>`<option ${h.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Industry<input name="v2_history_${i}_industry" maxlength="100" value="${esc(h.industry||'')}"></label><label class="full">Achievement in this role<input name="v2_history_${i}_achievement" maxlength="180" value="${esc(h.achievement||'')}"></label><label class="full">Skills used<input name="v2_history_${i}_skills" maxlength="180" value="${esc(h.skills||'')}" placeholder="Separate with commas"></label></div></fieldset>`);return i===0?entry:`<details class="job-details"><summary>Employment ${i+1} / 工作 ${i+1} · Optional</summary>${entry}</details>`};
profilePage=function(){let html=profileV1();const extra=`<section class="panel form-section" id="professional"><div class="section-title"><span>05</span><div><h2>Professional story</h2><p class="field-note">A concise view of your experience and outcomes.</p></div></div><label>Professional headline<input name="v2_headline" maxlength="120" value="${esc(talentV2.headline)}" placeholder="B2B Business Development | FMCG | Account Management"></label><label>Professional summary<textarea name="v2_summary" maxlength="500" placeholder="Describe your experience, strengths and the opportunities you seek.">${esc(talentV2.summary)}</textarea></label><p class="field-note">${talentV2.summary.length}/500 characters. Aim for 300–500 when you have enough to say.</p><button type="button" class="btn" onclick="showAssistant()">Improve with Stars AI · Coming later</button><div class="v2-divider"></div><h2>Skills</h2><p class="field-note">Add relevant skills and optional evidence. Existing job history stays intact.</p><div class="v2-entries">${talentV2.skills.map((s,i)=>`<div class="v2-entry form-grid"><label>Skill<input name="v2_skill_${i}_name" maxlength="60" value="${esc(s.name||'')}"></label><label>Years of experience<input type="number" min="0" max="60" step="0.5" name="v2_skill_${i}_years" value="${esc(s.years||'')}"></label><label>Proficiency<select name="v2_skill_${i}_level">${['','Beginner','Intermediate','Advanced','Expert'].map(v=>`<option ${s.level===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Supporting experience<input name="v2_skill_${i}_evidence" maxlength="150" value="${esc(s.evidence||'')}" placeholder="Role or project"></label></div>`).join('')}</div><button type="button" class="btn" onclick="addTalentEntry('skills')" ${talentV2.skills.length>=8?'disabled':''}>Add skill</button><div class="v2-divider"></div><h2>Key achievements</h2><p class="field-note">Short, outcome-focused achievements. Maximum 8.</p>${talentV2.achievements.map((a,i)=>`<label>Achievement ${i+1}<input name="v2_achievement_${i}" maxlength="180" value="${esc(a)}" placeholder="What changed because of your work?"></label>`).join('')}<button type="button" class="btn" onclick="addTalentEntry('achievements')" ${talentV2.achievements.length>=8?'disabled':''}>Add achievement</button><div class="v2-divider"></div><h2>Résumé / CV</h2><p class="field-note">No résumé attached. Upload, view and replace are unavailable until secure file storage is added.</p><button class="btn" type="button" disabled>Upload résumé · Coming later</button><p class="field-note">TODO: Add candidate-reviewed profile suggestions from résumé parsing only after a secure upload flow exists.</p></section>`;html=html.replace('<section class="panel form-section" id="consent">',extra+'<section class="panel form-section" id="consent">');html=html.replace('<section class="panel form-section" id="consent"><div class="section-title"><span>05</span>','<section class="panel form-section" id="consent"><div class="section-title"><span>06</span>');html=html.replace('05 Privacy & consent','06 Privacy & consent').replace('Your public-facing professional information','Your professional information');html=html.replace('<div class="profile-side">','<div class="profile-side"><section class="panel"><h2>Profile strength</h2><strong class="v2-score">'+strength().percent+'%</strong><progress max="100" value="'+strength().percent+'"></progress><p class="field-note">Based on useful career information. Optional private details do not count.</p></section>');return html};
captureProfile=function(form){legacyCaptureProfile(form);const f=new FormData(form);talentV2.headline=String(f.get('v2_headline')||'').trim();talentV2.summary=String(f.get('v2_summary')||'').trim();talentV2.skills=talentV2.skills.map((_,i)=>({name:String(f.get(`v2_skill_${i}_name`)||'').trim(),years:String(f.get(`v2_skill_${i}_years`)||''),level:String(f.get(`v2_skill_${i}_level`)||''),evidence:String(f.get(`v2_skill_${i}_evidence`)||'').trim()}));talentV2.achievements=talentV2.achievements.map((_,i)=>String(f.get(`v2_achievement_${i}`)||'').trim());talentV2.experienceExtras=[0,1,2].map(i=>Object.fromEntries(['type','industry','achievement','skills'].map(k=>[k,String(f.get(`v2_history_${i}_${k}`)||'').trim()]))) };
function addTalentEntry(kind){const form=document.querySelector('#talent-form');if(form)captureProfile(form);if(talentV2[kind].length>=8)return;talentV2[kind].push(kind==='skills'?{name:'',years:'',level:'',evidence:''}:'');render();document.querySelector(`[name="v2_${kind==='skills'?'skill_'+(talentV2.skills.length-1)+'_name':'achievement_'+(talentV2.achievements.length-1)}"]`)?.focus()}
completeProfile=function(e){const before=talentDraft.events.length;legacyCompleteProfile(e);if(talentDraft.events.length>before){talentV2.profileUpdatedAt=nowDate();talentV2.salaryConfirmedAt=talentDraft.salary?nowDate():null;if(talentDraft.discovery&&talentV2.visibility==='Hidden')talentV2.visibility='Public';render()}};
withdrawDiscovery=function(){legacyWithdrawDiscovery();talentV2.visibility='Hidden';render()};
function showAssistant(){modal(`<h2>Stars AI profile assistant</h2><p class="sub">This prototype has no AI service. Here are profile checks you can act on yourself.</p><ul class="v2-suggestions">${strength().missing.slice(0,5).map(([label])=>`<li>${esc(label)}</li>`).join('')||'<li>Your key career information is covered.</li>'}</ul><p class="field-note">TODO: Future AI suggestions must be reviewed and confirmed by the candidate before changes are saved.</p>`)}
previewEmployer=function(){const form=document.querySelector('#talent-form');if(form)captureProfile(form);const anonymous=talentV2.visibility==='Anonymous',hidden=talentV2.visibility==='Hidden'||!talentDraft.discovery;const p=employerData(talentDraft);modal(`<div class="eyebrow">EMPLOYER PREVIEW</div><h2>${anonymous?'Anonymous professional':esc(p.name||'Your name')}</h2><p class="sub">${esc(talentV2.headline||p.job||'Professional profile')}</p><div class="callout">${hidden?'Discovery is off. Employers cannot see this preview in a future enforced system.':'Illustrative preview for registered employers. Visibility is not enforced in this static prototype.'}</div><dl class="preview-list"><dt>Target role</dt><dd>${esc(p.job||'Not supplied')}</dd><dt>Qualification</dt><dd>${esc(p.qualification||'Not supplied')}</dd><dt>Skills</dt><dd>${esc(talentV2.skills.map(s=>s.name).filter(Boolean).join(', ')||'Not supplied')}</dd><dt>Location</dt><dd>${esc(p.location||'Not supplied')}</dd><dt>Availability</dt><dd>${esc(talentV2.status)}</dd><dt>Expected salary</dt><dd>${esc(p.salary?`${p.currency} ${p.salary}`:'Not supplied')}</dd></dl>${p.history.map(h=>`<div class="fit"><strong>${esc(h.position)}${anonymous?'':` · ${esc(h.company)}`}</strong>${esc(h.from)} – ${h.current?'Present':esc(h.to)}<p>${esc(h.description)}</p></div>`).join('')}<p class="field-note">Phone, email, personal details, past salary and reasons for leaving are excluded. Anonymous mode also hides your name and employers.</p>`)};
// TODO: Enforce visibility and current-employer exclusions server-side before enabling real employer access.
// TODO: Connect verified jobs and mutual matching before presenting a calculated percentage.
render();
